require("dotenv").config();const FtpDeploy=require("ftp-deploy"),path=require("path"),ftpDeploy=new FtpDeploy,config={user:process.env.FTP_USER,password:process.env.FTP_PASSWORD,host:process.env.FTP_HOST,port:parseInt(process.env.FTP_PORT,10)||21,localRoot:path.join(__dirname,"build"),remoteRoot:process.env.FTP_REMOTE_ROOT||"/",include:["*","**/*"],deleteRemote:!1,forcePasv:!0};ftpDeploy.deploy(config).then((res=>console.log("✅ FTP Deploy Finished:",res))).catch((err=>console.error("❌ FTP Deploy Error:",err)));